const apiUrl='https://dpenlftkwzqwhgpvutwk.supabase.co/functions/v1/inspection-api';
let data={departments:[],equipment:[],groups:[],forms:[],records:[]}, profile=null, view='board', department='', group='', query='', status='', shift='day', kind='daily';
let years=[new Date().getFullYear()-1,new Date().getFullYear()], editing=null, check=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
async function api(payload){payload=normalizeEquipmentImport(payload);const token=localStorage.getItem('inspection_token');const r=await fetch(apiUrl,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(payload)});const result=await r.json();if(!r.ok)throw Error(result.error||'error');return result;}
function toast(key,extra=''){const box=$('#toast');box.textContent=t(key)+(extra?' '+extra:'');box.classList.add('show');setTimeout(()=>box.classList.remove('show'),4500);}
function button(key,action,cls='secondary'){return `<button class="btn ${cls}" ${action}>${txt(key)}</button>`;}
function nameOf(row){if(row?.name_zh && NAME_TRANSLATIONS[row.name_zh])return multilingual(NAME_TRANSLATIONS[row.name_zh]);return multilingual(Object.fromEntries(['zh','en','es','vi'].map(l=>[l,row?.['name_'+l]||((l==='zh')?row?.equipment_name:'')])));}
function dateText(v){return v?new Date(v).toLocaleString({zh:'zh-TW',en:'en-US',es:'es-ES',vi:'vi-VN'}[primary]):'—';}
function options(rows,value,caption){return `<option value="">${txt(caption)}</option>`+rows.map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(nameOf(r))}</option>`).join('');}
function optionNameKey(value){return String(value||'').normalize('NFKC').trim().replace(/\s+/g,' ');}
function normalizeEquipmentImport(payload){
 const canonical=(name,rows)=>{const key=optionNameKey(name);return rows.find(r=>optionNameKey(r.name_zh)===key)?.name_zh||key;};
 if(payload.action==='equipment_mapping_import'&&Array.isArray(payload.rows))return {...payload,rows:payload.rows.map(row=>{let dept=optionNameKey(row.department);if(dept==='精密車修'&&data.departments.some(d=>d.name_zh==='精密車修組'))dept='精密車修組';dept=canonical(dept,data.departments);const d=data.departments.find(d=>d.name_zh===dept);return {...row,department:dept,equipment_group:canonical(row.equipment_group,data.groups.filter(g=>g.department_id===d?.id))};})};
 if(payload.action==='equipment_save')return {...payload,equipment_group:canonical(payload.equipment_group,data.groups.filter(g=>g.department_id===payload.department_id))};
 return payload;
}
function uniqueNamedOptions(rows){const names=new Set();return rows.filter(r=>{const key=optionNameKey(r.name_zh);if(!key||names.has(key))return false;names.add(key);return true;});}
function matchesDepartment(id,selected=department){if(!selected)return true;const a=data.departments.find(d=>d.id===id),b=data.departments.find(d=>d.id===selected);return id===selected||!!(a&&b&&optionNameKey(a.name_zh)===optionNameKey(b.name_zh));}
function matchesGroup(e,selected=group){if(!selected)return true;const a=data.groups.find(g=>g.id===e.equipment_group_id),b=data.groups.find(g=>g.id===selected);return e.equipment_group_id===selected||!!(a&&b&&optionNameKey(a.name_zh)===optionNameKey(b.name_zh));}
function hidesCraneCards(){return ['board','visual','qr03','qr04','backfill'].includes(view);}
function isCraneEquipment(e){return /天車|起重機/.test((e.name_zh||'')+' '+(e.equipment_groups?.name_zh||data.groups.find(g=>g.id===e.equipment_group_id)?.name_zh||''));}
function filters(){const depts=uniqueNamedOptions(data.departments),groups=uniqueNamedOptions(data.groups.filter(g=>matchesDepartment(g.department_id)&&(!hidesCraneCards()||!/天車|起重機/.test(g.name_zh))));const selectedDept=data.departments.find(d=>d.id===department),selectedGroup=data.groups.find(g=>g.id===group);if(selectedDept)department=depts.find(d=>optionNameKey(d.name_zh)===optionNameKey(selectedDept.name_zh))?.id||'';if(selectedGroup)group=groups.find(g=>optionNameKey(g.name_zh)===optionNameKey(selectedGroup.name_zh))?.id||'';return `<div class="filter-row"><label>${txt('department')}<select class="select" id="deptFilter">${options(depts,department,'all')}</select></label><label>${txt('group')}<select class="select" id="groupFilter">${options(groups,group,'all')}</select></label></div>`;}
function filteredEquipment(){if(hidesCraneCards()&&/天車|起重機/.test(data.groups.find(g=>g.id===group)?.name_zh||''))group='';return data.equipment.filter(e=>matchesDepartment(e.department_id)&&matchesGroup(e)&&(!hidesCraneCards()||!isCraneEquipment(e)));}
function latest(e){return data.records.find(r=>r.equipment_id===e.id&&r.shift===shift&&new Date(r.inspected_at).toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'})===new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'}));}
function state(e){const r=latest(e);return r?(r.approval_status==='rejected'?'rejected':r.is_draft?'draft':r.overall_status):'pending';}
function canManage(){return profile&&['admin','supervisor'].includes(profile.role);}
function formMatches(f,e){return (data.assignments||[]).some(a=>a.equipment_id===e.id&&a.form_id===f.id&&a.kind===f.kind);}
function formList(){const d=data.departments.find(d=>d.id===department),g=data.groups.find(g=>g.id===group);return data.forms.filter(f=>{const assigned=data.equipment.filter(e=>(data.assignments||[]).some(a=>a.form_id===f.id&&a.equipment_id===e.id));return f.kind===kind&&(!d||f.department===d.name_zh||assigned.some(e=>matchesDepartment(e.department_id,d.id)))&&(!g||f.equipment_group===g.name_zh||assigned.some(e=>matchesGroup(e,g.id)));});}
function header(){return `<header class="topbar"><div class="brand"><span class="brand-mark">✓</span>${txt('brand')}</div><div class="top-actions"><label>${txt('primary')}<select id="primaryLanguage" class="select">${Object.entries(localeNames).map(([k,v])=>`<option value="${k}" ${k===primary?'selected':''}>${v}</option>`).join('')}</select></label><label>${txt('secondary')}<select id="secondaryLanguage" class="select"><option value="">${txt('none')}</option>${Object.entries(localeNames).map(([k,v])=>`<option value="${k}" ${k===secondary?'selected':''}>${v}</option>`).join('')}</select></label>${fontSizeControls()}${button(profile?'logout':'login','id="loginButton"')}</div></header>`;}
function render(){document.documentElement.lang={zh:'zh-Hant',en:'en',es:'es',vi:'vi'}[primary];document.title=t('brand');const nav=[['field',['board','backfill','history','visual','fireDaily']],['supervisor',['approval','daily','maintenance','items','assignment']],['backoffice',['mapping','settings','database']]];$('#app').innerHTML=header()+`<div class="layout"><aside class="side">${nav.map(([section,keys])=>`<div class="side-label">${txt(section)}</div>${keys.map(k=>`<button class="nav ${view===k?'active':''}" data-view="${k}">${txt(k)}</button>`).join('')}`).join('')}</aside><main class="main"><div class="page-title"><h1>${txt(view)}</h1>${profile?button('refresh','id="refresh"'):''}</div><div id="content"></div></main></div>`;$('#primaryLanguage').onchange=e=>{primary=e.target.value;changeLanguage();};$('#secondaryLanguage').onchange=e=>{secondary=e.target.value;changeLanguage();};bindFontSizes();$('#loginButton').onclick=profile?logout:showLogin;$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;if(view==='daily'||view==='maintenance')kind=view;render();});if($('#refresh'))$('#refresh').onclick=load;applySize();renderContent();}
function applySize(){document.documentElement.style.fontSize=languageFontSize('inspection_font_size')+'px';document.documentElement.style.setProperty('--secondary-font-size',languageFontSize('inspection_secondary_font_size')+'px');}
function changeLanguage(){localStorage.setItem('primary_language',primary);localStorage.setItem('secondary_language',secondary);render();if($('#loginDialog'))showLogin(true);if(editing)renderEditor();if(check)renderCheck();}
function renderContent(){const c=$('#content');if(!profile){c.innerHTML=`<div class="empty-note">${txt('loginFirst')}</div>`;return;}if(view==='board')renderBoard();else if(view==='backfill')renderBackfill();else if(view==='history')renderHistory();else if(view==='visual')renderVisual();else if(view==='fireDaily')window.renderFireDaily();else if(view==='approval')renderApprovals();else if(['daily','maintenance','items'].includes(view))renderForms();else if(view==='mapping')renderMapping();else if(view==='assignment')renderAssignments();else if(view==='database')renderDatabase();else renderSettings();$$('#deptFilter,#groupFilter').forEach(el=>el.onchange=()=>{department=$('#deptFilter').value;group=el.id==='deptFilter'?'':$('#groupFilter').value;renderContent();});}
function table(head,rows){return `<div class="table-wrap"><table class="matrix"><thead><tr>${head.map(h=>`<th>${txt(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${head.length}">${txt('noData')}</td></tr>`}</tbody></table></div>`;}
function renderBoard(){const list=filteredEquipment();const metrics=[['scheduled',list.length],['completed',list.filter(e=>['normal','abnormal'].includes(state(e))).length],['pending',list.filter(e=>['pending','draft','rejected'].includes(state(e))).length],['abnormal',list.filter(e=>state(e)==='abnormal').length]];const percentage=list.length?Math.round(metrics[1][1]/list.length*100):0;$('#content').innerHTML=`${filters()}<div class="overview">${metrics.map(([k,v])=>`<button class="metric" data-status="${{scheduled:'',completed:'completed',pending:'pending',abnormal:'abnormal'}[k]}"><div class="label">${txt(k)}</div><div class="value">${v}</div></button>`).join('')}</div><div class="progress-wrap"><b>${txt('completion')} ${percentage}%</b><div class="bar"><i style="width:${percentage}%"></i></div></div><div class="filter-row"><label>${txt('inspector')}<input id="inspector" class="select" value="${esc(localStorage.getItem('inspection_operator_name')||'')}"></label><label>${txt('search')}<input id="search" class="select" value="${esc(query)}"></label><select id="shift" class="select" aria-label="${txt('day')}">${['day','night'].map(k=>`<option value="${k}" ${shift===k?'selected':''}>${txt(k)}</option>`).join('')}</select><select id="status" class="select" aria-label="${txt('status')}">${['','pending','draft','normal','abnormal','completed'].map(k=>`<option value="${k}" ${status===k?'selected':''}>${txt(k||'all')}</option>`).join('')}</select></div><div id="equipmentBoard" class="board"></div>`;$('#inspector').oninput=e=>localStorage.setItem('inspection_operator_name',e.target.value);$('#search').oninput=e=>{query=e.target.value;cards();};$('#shift').onchange=e=>{shift=e.target.value;renderContent();};$('#status').onchange=e=>{status=e.target.value;cards();};$$('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;renderContent();});cards();}
function cards(){const list=filteredEquipment().filter(e=>(!query||`${e.equipment_code} ${e.name_zh} ${e.name_en||''} ${e.machine_no}`.toLowerCase().includes(query.toLowerCase()))&&(!status||(status==='completed'?['normal','abnormal'].includes(state(e)):status==='pending'?['pending','draft','rejected'].includes(state(e)):state(e)===status)));$('#equipmentBoard').innerHTML=list.map(e=>{const r=latest(e);return `<article class="equipment ${state(e)}"><div class="stripe"></div><div class="equipment-body"><div class="eq-head"><strong>${esc(e.equipment_code)}</strong><span class="tag ${state(e)}">${txt(state(e))}</span></div><h3>${esc(nameOf(e))}</h3><p>${txt('group')}：${e.equipment_groups?esc(nameOf(e.equipment_groups)):txt('unassigned')}<br>${txt('machineNo')}：${esc(e.machine_no||'—')}<br>${txt('propertyNo')}：${esc(e.property_no||'—')}</p><p>${txt('inspector')}：${esc(r?.inspector_name||'—')}<br>${txt('latest')}：${dateText(r?.inspected_at)}</p><div class="eq-bottom">${button(r&&!r.is_draft&&r.approval_status!=='rejected'?'alreadyInspected':'start',`data-check="${e.id}" ${r&&!r.is_draft&&r.approval_status!=='rejected'?'disabled':data.forms.some(f=>f.kind==='daily'&&formMatches(f,e))?'':'disabled'}`)}${data.forms.some(f=>f.kind==='daily'&&formMatches(f,e))?'':`<span class="muted">${txt('assignFirst')}</span>`}${r?button('details',`data-record="${r.id}"`):''}</div></div></article>`;}).join('')||`<div class="empty-note">${txt('noData')}</div>`;$$('[data-check]').forEach(b=>b.onclick=()=>startCheck(b.dataset.check));bindRecords();}
function bindRecords(){$$('[data-record]').forEach(b=>b.onclick=()=>recordDetail(b.dataset.record));}
function renderHistory(){const ids=new Set(filteredEquipment().map(e=>e.id));$('#content').innerHTML=filters()+table(['date','equipmentCode','equipmentName','inspector','result','approval','actions'],data.records.filter(r=>ids.has(r.equipment_id)).map(r=>{const e=data.equipment.find(e=>e.id===r.equipment_id);return `<tr><td>${dateText(r.inspected_at)}</td><td>${esc(e?.equipment_code)}</td><td>${esc(nameOf(e))}</td><td>${esc(r.inspector_name||'—')}</td><td>${txt(r.overall_status)}</td><td>${txt(r.approval_status==='pending'?'awaiting':r.approval_status)}</td><td>${button('details',`data-record="${r.id}"`)}</td></tr>`;}).join(''));bindRecords();}
function renderVisual(){const available=[...new Set([new Date().getFullYear()-1,new Date().getFullYear(),...years,...Array.from({length:12},(_,i)=>new Date().getFullYear()-6+i),...data.records.map(r=>new Date(r.inspected_at).getFullYear())])].sort((a,b)=>b-a);$('#content').innerHTML=filters()+`<div class="filter-row">${years.map((y,i)=>`<label>${txt(i?'year2':'year')}<select class="select" data-year="${i}">${available.map(v=>`<option ${v===y?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><p>${txt('monthlyView')}</p><div class="year-grid">${years.map(y=>`<section><h2>${y}</h2><div class="table-wrap"><table class="matrix"><thead><tr><th>${txt('equipmentCode')}</th>${Array.from({length:12},(_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${filteredEquipment().map(e=>`<tr><td>${esc(e.equipment_code)}</td>${Array.from({length:12},(_,i)=>{const rs=data.records.filter(r=>r.equipment_id===e.id&&!r.is_draft&&new Date(r.inspected_at).getFullYear()===y&&new Date(r.inspected_at).getMonth()===i);return `<td><span class="tag ${rs.some(r=>r.overall_status==='abnormal')?'abnormal':rs.length?'normal':''}" title="${txt(rs.length?'completed':'noRecord')}">${rs.length||'—'}</span></td>`;}).join('')}</tr>`).join('')||`<tr><td colspan="13">${txt('noData')}</td></tr>`}</tbody></table></div></section>`).join('')}</div>`;$$('[data-year]').forEach(s=>s.onchange=()=>{years[+s.dataset.year]=+s.value;renderContent();});}
function renderApprovals(){const ids=new Set(filteredEquipment().map(e=>e.id));$('#content').innerHTML=filters()+table(['date','equipmentCode','inspector','result','actions'],data.records.filter(r=>ids.has(r.equipment_id)&&r.approval_status==='pending'&&!r.is_draft).map(r=>`<tr><td>${dateText(r.inspected_at)}</td><td>${esc(data.equipment.find(e=>e.id===r.equipment_id)?.equipment_code)}</td><td>${esc(r.inspector_name)}</td><td>${txt(r.overall_status)}</td><td>${button('details',`data-record="${r.id}"`)}${canManage()?button('approve',`data-approve="${r.id}"`,'primary')+button('reject',`data-reject="${r.id}"`,'danger'):''}</td></tr>`).join(''));bindRecords();$$('[data-approve],[data-reject]').forEach(b=>b.onclick=async()=>{try{await api({action:'record_approve',id:b.dataset.approve||b.dataset.reject,approve:!!b.dataset.approve});await load();toast('saved');}catch{toast('error');}});}
function renderForms(){$('#content').innerHTML=(view==='items'?`<select id="kind" class="select">${['daily','maintenance'].map(k=>`<option value="${k}" ${kind===k?'selected':''}>${txt(k)}</option>`).join('')}</select>`:'')+filters()+`<div class="filter-row">${button('download','id="download"')}${button('export','id="export"')}${canManage()?button('add','id="add"','primary'):''}</div>${canManage()?`<div class="approval"><label>${txt('selectFile')}<input id="formFile" type="file" accept=".xlsx,.xls,.csv"></label>${button('import','id="import"','primary')}</div><p class="muted">${txt('importHelp')}</p>`:`<p>${txt('readOnly')}</p>`}`+table(['fileName','department','group','equipmentName','machineNo','propertyNo','source','updated','actions'],formList().map(f=>`<tr><td>${esc(f.form_name)}</td><td>${(f.department?esc(localName(f.department)):txt('unassigned'))}</td><td>${f.equipment_group?esc(localName(f.equipment_group)):txt('unassigned')}</td><td>${esc(localName(f.equipment_name))}</td><td>${esc(f.machine_no||'—')}</td><td>${esc(f.property_no||'—')}</td><td>${esc(f.source_filename)}<br>${esc(f.source_sheet)}<br>${esc(localName(f.source_department||''))}</td><td>${dateText(f.updated_at)}</td><td>${button('details',`data-form="${f.id}"`)+button('downloadOne',`data-download-form="${f.id}"`)+(canManage()?button('assign',`data-assign-form="${f.id}"`,'primary'):'')}${canManage()?button('edit',`data-edit="${f.id}"`)+button('delete',`data-delete="${f.id}"`,'danger'):''}</td></tr>`).join(''));if($('#kind'))$('#kind').onchange=e=>{kind=e.target.value;renderContent();};$('#download').onclick=()=>downloadForms(true);$('#export').onclick=downloadSeparateForms;$$('[data-download-form]').forEach(b=>b.onclick=()=>downloadOneForm(b.dataset.downloadForm));$$('[data-assign-form]').forEach(b=>b.onclick=()=>openAssignment(b.dataset.assignForm));if($('#add'))$('#add').onclick=()=>editForm();if($('#import'))$('#import').onclick=importForms;$$('[data-form]').forEach(b=>b.onclick=()=>formDetail(b.dataset.form));$$('[data-edit]').forEach(b=>b.onclick=()=>editForm(b.dataset.edit));$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(t('deleteConfirm')))return;try{await api({action:'form_delete',id:b.dataset.delete});await load();toast('deleted');}catch{toast('error');}});}
function localName(value){return NAME_TRANSLATIONS[value]?multilingual(NAME_TRANSLATIONS[value]):value;}
function dialog(id,title,body,footer=''){let old=document.getElementById(id);const savedScroll=id==='check'?{top:old?.querySelector('.dialog-body')?.scrollTop||0,left:old?.querySelector('.dialog-body')?.scrollLeft||0}:null;old?.remove();const m=document.createElement('div');m.className='modal open';m.id=id;m.innerHTML=`<div class="dialog"><div class="dialog-head"><h2>${esc(title)}</h2><button class="x" aria-label="${txt('close')}">×</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-foot">${footer}</div>`:''}</div>`;m.querySelector('.x').onclick=()=>{m.remove();if(id==='editor')editing=null;if(id==='check')check=null;};document.body.append(m);if(savedScroll)requestAnimationFrame(()=>{const body=m.querySelector('.dialog-body');if(body){body.scrollTop=savedScroll.top;body.scrollLeft=savedScroll.left;}});return m;}
function itemTable(items){return table(['order','item','standard','method','cycle'],items.map((i,n)=>`<tr><td>${n+1}</td>${['name','standard','method','cycle'].map(k=>`<td>${esc(multilingual(i[k]))}</td>`).join('')}</tr>`).join(''));}
function formDetail(id){const f=data.forms.find(x=>x.id===id);dialog('detail',localName(f.equipment_name),`<p>${txt('department')}: ${(f.department?esc(localName(f.department)):txt('unassigned'))} · ${txt('machineNo')}: ${esc(f.machine_no||'—')} · ${txt('propertyNo')}: ${esc(f.property_no||'—')}</p>${itemTable(f.items)}`);}
function recordDetail(id){const r=data.records.find(x=>x.id===id);dialog('detail',t('history'),`<p>${dateText(r.inspected_at)} · ${esc(r.inspector_name||'—')} · ${txt(r.overall_status)}</p>`+table(['item','result','reason','photo'],(r.answers||[]).map(a=>`<tr><td>${esc(multilingual(a.item?.name))}</td><td>${a.value?txt(a.value==='maintenance'?'maintenanceResult':a.value):txt('pending')}</td><td>${esc(a.note)}</td><td>${/^data:image\/(png|jpeg|webp);base64,/.test(a.photo||'')?`<img class="record-photo" src="${esc(a.photo)}" alt="${txt('photo')}">`:'—'}</td></tr>`).join('')));}
const emptyText=()=>({zh:'',en:'',es:'',vi:''});const blankItem=()=>({name:emptyText(),standard:emptyText(),method:emptyText(),cycle:emptyText()});
function editForm(id){editing=structuredClone(data.forms.find(f=>f.id===id)||{kind,form_name:'',department:data.departments.find(d=>d.id===department)?.name_zh||data.departments[0]?.name_zh||'',equipment_group:data.groups.find(g=>g.id===group)?.name_zh||'',equipment_name:'',machine_no:'',property_no:'',items:[blankItem()]});renderEditor();}
function renderEditor(){const f=editing;const m=dialog('editor',t('edit')+' · '+t(f.kind),`<div class="editor-fields">${[['form_name','fileName'],['department','department'],['equipment_group','group'],['equipment_name','equipmentName'],['machine_no','machineNo'],['property_no','propertyNo']].map(([k,label])=>`<label>${txt(label)}${k==='department'?`<select class="select" data-field="${k}">${['',...data.departments.map(d=>d.name_zh)].map(d=>`<option value="${esc(d)}" ${d===f.department?'selected':''}>${d?esc(localName(d)):txt('unassigned')}</option>`).join('')}</select>`:k==='equipment_group'?`<input class="select" list="groupNames" data-field="${k}" value="${esc(f[k])}"><datalist id="groupNames">${data.groups.filter(g=>data.departments.find(d=>d.id===g.department_id)?.name_zh===f.department).map(g=>`<option value="${esc(g.name_zh)}">${esc(nameOf(g))}</option>`).join('')}</datalist>`:`<input class="select" data-field="${k}" value="${esc(f[k])}">`}</label>`).join('')}</div><h3>${txt('translations')}</h3>${f.items.map((it,n)=>`<div class="item"><strong>${n+1}</strong>${button('removeItem',`data-remove="${n}"`,'danger')}<div class="translation-grid">${['zh','en','es','vi'].map(l=>`<section><h4>${localeNames[l]}</h4>${[['name','item'],['standard','standard'],['method','method'],['cycle','cycle']].map(([k,label])=>`<label>${txt(label)}<textarea data-item="${n}" data-key="${k}" data-lang="${l}">${esc(it[k]?.[l])}</textarea></label>`).join('')}</section>`).join('')}</div></div>`).join('')}`,button('addItem','id="addItem"')+button('save','id="saveForm"','primary'));m.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{editing[el.dataset.field]=el.value;});m.querySelector('[data-field="department"]').onchange=e=>{editing.department=e.target.value;editing.equipment_group='';renderEditor();};m.querySelectorAll('textarea').forEach(el=>el.oninput=()=>editing.items[+el.dataset.item][el.dataset.key][el.dataset.lang]=el.value);m.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{editing.items.splice(+b.dataset.remove,1);renderEditor();});$('#addItem').onclick=()=>{editing.items.push(blankItem());renderEditor();};$('#saveForm').onclick=async()=>{if(!editing.form_name?.trim()||(profile.role!=='admin'&&!editing.department)||!editing.equipment_name||!editing.items.length||editing.items.some(i=>!i.name.zh.trim())){toast('formRequired');return;}try{await api({action:'form_save',form:editing});editing=null;m.remove();await load();toast('saved');}catch{toast('error');}};}
const formColumns=['表單編號','檔名','表單類型','部門','設備群組','設備名稱','機台編號','財產編號','順序',...['項目','判定基準','檢查方法','保養週期'].flatMap(k=>['zh','en','es','vi'].map(l=>k+'_'+l))];
function csvCell(v){let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function csvDownload(name,columns,rows){const blob=new Blob(['\ufeff'+[columns,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function downloadForms(blank){const fs=blank?[]:formList();const rows=fs.flatMap((f,idx)=>f.items.map((i,n)=>[f.id||'FORM-'+(idx+1),f.form_name||'',f.kind,f.department,f.equipment_group,f.equipment_name,f.machine_no,f.property_no,n+1,...['name','standard','method','cycle'].flatMap(k=>['zh','en','es','vi'].map(l=>i[k]?.[l]||''))]));if(blank)rows.push(['FORM-1','',kind,data.departments.find(d=>d.id===department)?.name_zh||'',data.groups.find(g=>g.id===group)?.name_zh||'','','','',1,...Array(16).fill('')]);csvDownload(`${kind}-${blank?'template':'data'}-${data.departments.find(d=>d.id===department)?.name_zh||'all'}.csv`,formColumns,rows);}
async function readRows(file){if(!file)throw Error('file');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'});return XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{defval:'',raw:false});}
async function importForms(){const b=$('#import');b.disabled=true;try{const file=$('#formFile').files[0],rows=await readRows(file),map=new Map();for(const r of rows){if(!r['設備名稱']||!r['項目_zh'])throw Error('invalid');const id=r['表單編號']||JSON.stringify([r['部門'],r['設備名稱'],r['機台編號'],r['財產編號']]);if(!map.has(id))map.set(id,{kind,form_name:r['檔名']||file.name.replace(/\.[^.]+$/,'')+'.csv',department:r['部門'],equipment_group:r['設備群組']||'',equipment_name:r['設備名稱'],machine_no:r['機台編號']||'',property_no:r['財產編號']||'',items:[],source_filename:file.name});const f=map.get(id);if(f.department!==r['部門']||f.equipment_name!==r['設備名稱']||f.machine_no!==(r['機台編號']||''))throw Error('inconsistent');const i={order:Number(r['順序'])||f.items.length+1};for(const [k,c] of [['name','項目'],['standard','判定基準'],['method','檢查方法'],['cycle','保養週期']])i[k]=Object.fromEntries(['zh','en','es','vi'].map(l=>[l,r[c+'_'+l]||'']));f.items.push(i);}const forms=[...map.values()];forms.forEach(f=>f.items.sort((a,b)=>a.order-b.order));const result=await api({action:'forms_import',forms,filename:file.name});await load();toast('imported',String(result.success));}catch{toast('invalidFile');}finally{b.disabled=false;}}
function renderMapping(){$('#content').innerHTML=filters()+`<p>${txt('mappingHelp')}</p><details class="import-rules"><summary>${esc(multilingual({zh:'部門與設備群組整合規則',en:'Department and group rules',es:'Reglas de departamentos y grupos',vi:'Quy tắc bộ phận và nhóm'}))}</summary><p>${esc(multilingual({zh:'同名部門與群組在選單只顯示一次；全部部門可查詢各部門的同名群組。匯入會整理名稱前後空白、全半形及連續空白，同一部門的同名群組沿用既有資料。不同部門的設備歸屬保留；10T天車與天車等不同名稱不會自動合併。精密車修統一使用精密車修組。',en:'Identical department and group names appear once. A group filter includes matching groups across departments. Imports normalize surrounding spaces, repeated spaces and character width, and reuse matching groups within the department. Equipment ownership stays unchanged. Different names, such as 10T crane and crane, stay separate.',es:'Los nombres iguales aparecen una sola vez. El filtro incluye grupos del mismo nombre entre departamentos. La importación normaliza espacios y reutiliza los grupos del departamento. Se conservan la pertenencia de los equipos y los nombres diferentes.',vi:'Tên bộ phận và nhóm giống nhau chỉ hiển thị một lần. Bộ lọc bao gồm nhóm cùng tên ở các bộ phận. Khi nhập sẽ chuẩn hóa khoảng trắng và dùng lại nhóm hiện có. Giữ nguyên bộ phận của thiết bị và các tên khác nhau.'}))}</p></details><div class="approval"><label>${txt('selectFile')}<input id="mappingFile" type="file" accept=".xlsx,.xls,.csv"></label>${canManage()?button('import','id="mappingImport"','primary'):''}${button('download','id="mappingDownload"')}${button('export','id="mappingExport"')}</div>`+table(['department','group','equipmentCode','equipmentName','machineNo','propertyNo'],filteredEquipment().map(e=>`<tr><td>${esc(nameOf(data.departments.find(d=>d.id===e.department_id)))}</td><td>${e.equipment_groups?esc(nameOf(e.equipment_groups)):txt('unassigned')}</td><td>${esc(e.equipment_code)}</td><td>${esc(nameOf(e))}</td><td>${esc(e.machine_no)}</td><td>${esc(e.property_no)}</td></tr>`).join(''));$('#mappingDownload').onclick=()=>csvDownload('equipment-template.csv',['部門','設備群組','設備編號','設備名稱','機台編號','財產編號'],[]);$('#mappingExport').onclick=()=>csvDownload('equipment-data.csv',['部門','設備群組','設備編號','設備名稱','機台編號','財產編號'],filteredEquipment().map(e=>[data.departments.find(d=>d.id===e.department_id)?.name_zh,e.equipment_groups?.name_zh,e.equipment_code,e.name_zh,e.machine_no,e.property_no]));if($('#mappingImport'))$('#mappingImport').onclick=async()=>{const b=$('#mappingImport');b.disabled=true;try{const file=$('#mappingFile').files[0],rows=(await readRows(file)).map(r=>({department:r['部門']||r['組別'],equipment_group:r['設備群組'],equipment_code:r['設備編號']||r["'ALLDATA'[設備編號]"],equipment_name:r['設備名稱'],machine_no:r['機台編號']||'',property_no:r['財產編號']||''}));const result=await api({action:'equipment_mapping_import',filename:file.name,rows});await load();toast('imported',String(result.success));if(result.errors?.length)dialog('errors',t('invalidFile'),`<pre>${esc(result.errors.join('\n'))}</pre>`);}catch{toast('invalidFile');}finally{b.disabled=false;}};}
async function renderSettings(){if(profile.role!=='admin'){$('#content').innerHTML=`<p>${txt('readOnly')}</p>`;return;}$('#content').innerHTML=txt('loading');try{const result=await api({action:'admin_accounts'});if(!['settings','accounts'].includes(view))return;$('#content').innerHTML=`<p class="notice">${txt('passwordInfo')}</p><label>${txt('search')}<input id="accountSearch" class="select" type="search"></label>`+table(['account','fullName','department','role','status','actions'],result.accounts.map(a=>`<tr><td>${esc(a.account_code)}</td><td>${esc(a.full_name||'—')}</td><td>${(result.departments.some(d=>d.id===a.department_id)?esc(localName(a.departments?.name_zh||'')):txt('unassigned'))}</td><td>${txt(a.role)}</td><td>${txt(a.is_active?'active':'inactive')}</td><td>${button('copyAccount',`data-copy-account="${esc(a.account_code)}"`)}${button('resetPassword',`data-reset-account="${a.id}"`)}${button('edit',`data-account="${a.id}"`)}${a.is_active?button('disable',`data-disable="${a.id}"`,'danger'):''}</td></tr>`).join(''))+button('newAccount','id="newAccount"','primary');$('#accountSearch').oninput=e=>{$$('#content tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.trim().toLowerCase()));};$$('[data-copy-account]').forEach(b=>b.onclick=()=>copyAccountValue(b.dataset.copyAccount));$$('[data-reset-account]').forEach(b=>b.onclick=()=>resetAccountPassword(result.accounts.find(a=>a.id===b.dataset.resetAccount)));$('#newAccount').onclick=()=>accountEditor(null,result.departments);$$('[data-account]').forEach(b=>b.onclick=()=>accountEditor(result.accounts.find(a=>a.id===b.dataset.account),result.departments));$$('[data-disable]').forEach(b=>b.onclick=async()=>{if(!confirm(t('disableConfirm')))return;try{await api({action:'admin_account_delete',id:b.dataset.disable});renderSettings();}catch{toast('error');}});}catch{toast('error');}}
function accountEditor(a,depts){const m=dialog('accountEditor',t(a?'edit':'newAccount'),`<div class="editor-fields">${!a?`<label>${txt('account')}<input id="accountCode" class="select"></label>`:''}<label>${txt('fullName')}<input id="accountName" class="select" value="${esc(a?.full_name||'')}"></label><label>${txt('newPassword')}<input id="accountPassword" type="password" class="select" placeholder="${txt('passwordHint')}"></label><label>${txt('department')}<select id="accountDept" class="select"><option value="">${txt('unassigned')}</option>${depts.map(d=>`<option value="${d.id}" ${d.id===a?.department_id?'selected':''}>${esc(localName(d.name_zh))}</option>`).join('')}</select></label><label>${txt('role')}<select id="accountRole" class="select">${['operator','supervisor','admin'].map(r=>`<option value="${r}" ${a?.role===r?'selected':''}>${txt(r)}</option>`).join('')}</select></label></div>`,button('save','id="saveAccount"','primary'));$('#saveAccount').onclick=async()=>{if(!$('#accountDept').value){toast('required');return;}try{await api({action:a?'admin_account_update':'admin_account_create',id:a?.id,account_code:$('#accountCode')?.value,full_name:$('#accountName').value,password:$('#accountPassword').value,department_id:$('#accountDept').value,role:$('#accountRole').value});m.remove();renderSettings();toast('saved');}catch{toast('error');}};}
function showLogin(preserve=false){const account=preserve?$('#loginAccount')?.value||'':'',password=preserve?$('#loginPassword')?.value||'':'';const m=dialog('loginDialog',t('login'),`<p>${txt('credentials')}</p><form id="loginForm"><label>${txt('account')}<input id="loginAccount" class="select" autocomplete="username" required value="${esc(account)}"></label><label>${txt('password')}<input id="loginPassword" type="password" class="select" autocomplete="current-password" required></label><p id="loginError" role="alert"></p><button class="btn primary" type="submit">${txt('login')}</button></form>`);$('#loginPassword').value=password;$('#loginForm').onsubmit=async e=>{e.preventDefault();const btn=m.querySelector('[type="submit"]');btn.disabled=true;try{const result=await api({action:'login',account_code:$('#loginAccount').value.trim(),password:$('#loginPassword').value});localStorage.setItem('inspection_token',result.token);profile=result.profile;m.remove();render();}catch{$('#loginError').textContent=t('invalidLogin');}finally{btn.disabled=false;}};}
function logout(){localStorage.removeItem('inspection_token');profile=null;data={departments:[],equipment:[],groups:[],forms:[],records:[]};department='';group='';render();}
async function load(){try{const result=await api({action:'workspace'});data=result;profile=result.profile;render();}catch{toast('error');}}
function startCheck(eid){if(!localStorage.getItem('inspection_operator_name')?.trim()){toast('nameRequired');return;}const e=data.equipment.find(e=>e.id===eid),forms=data.forms.filter(f=>f.kind==='daily'&&formMatches(f,e));if(!forms.length){toast('noForm');return;}check={equipment:e,forms,form:forms[0],answers:forms[0].items.map(item=>({item,value:'',note:'',photo:''}))};const draft=latest(e);if(draft?.is_draft&&draft.form_id===forms[0].id&&draft.answers?.length===forms[0].items.length&&JSON.stringify(draft.answers.map(a=>a.item))===JSON.stringify(forms[0].items))check.answers=structuredClone(draft.answers);renderCheck();}
function renderCheck(){const c=check;const m=dialog('check',c.equipment.equipment_code+' · '+nameOf(c.equipment),`${powerCheckButton('quickPass','id="quickPass"')}<label>${txt('chooseForm')}<select id="checkForm" class="select">${c.forms.map(f=>`<option value="${f.id}" ${f.id===c.form.id?'selected':''}>${esc(localName(f.equipment_name))} ${esc(f.source_sheet)}</option>`).join('')}</select></label>${c.answers.map((a,n)=>`<div class="item"><h3>${n+1}. ${esc(multilingual(a.item.name))}</h3><p>${txt('standard')}：${esc(multilingual(a.item.standard))}</p><p>${txt('method')}：${esc(multilingual(a.item.method))}</p><div class="answers">${['normal','maintenance','disable'].map(v=>`<button class="choice ${a.value===v?'selected':''}" data-answer="${n}" data-value="${v}">${txt(v==='maintenance'?'maintenanceResult':v)}</button>`).join('')}</div><label>${txt('reason')}<textarea data-note="${n}">${esc(a.note)}</textarea></label><label>${txt('photo')}<input type="file" accept="image/png,image/jpeg,image/webp" data-photo="${n}"></label>${a.photo?`<img class="record-photo" src="${esc(a.photo)}" alt="${txt('photo')}">`:''}</div>`).join('')}`,button('saveDraft','id="saveDraft"')+button('submit','id="submitCheck"','primary'));$('#checkForm').onchange=e=>{c.form=c.forms.find(f=>f.id===e.target.value);c.answers=c.form.items.map(item=>({item,value:'',note:'',photo:''}));renderCheck();};$$('[data-answer]').forEach(b=>b.onclick=()=>{c.answers[+b.dataset.answer].value=b.dataset.value;b.closest('.answers').querySelectorAll('[data-answer]').forEach(choice=>{choice.classList.toggle('selected',choice.dataset.value===b.dataset.value);choice.setAttribute('aria-pressed',String(choice.dataset.value===b.dataset.value));});});$$('[data-note]').forEach(el=>el.oninput=()=>c.answers[+el.dataset.note].note=el.value);$$('[data-photo]').forEach(el=>el.onchange=async()=>{const f=el.files[0];if(!f||f.size>2000000||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('invalidFile');return;}const reader=new FileReader();reader.onload=()=>{c.answers[+el.dataset.photo].photo=reader.result;renderCheck();};reader.readAsDataURL(f);});$('#quickPass').onclick=()=>{c.answers.forEach(a=>a.value='normal');$$('#check [data-answer]').forEach(b=>{b.classList.toggle('selected',b.dataset.value==='normal');b.setAttribute('aria-pressed',String(b.dataset.value==='normal'));});};$('#saveDraft').onclick=()=>saveCheck(true);$('#submitCheck').onclick=()=>saveCheck(false);}
async function saveCheck(draft){if(!draft&&check.answers.some(a=>!a.value||(a.value!=='normal'&&!a.note.trim()))){toast('incomplete');return;}try{await api({action:'record_save',equipment_id:check.equipment.id,form_id:check.form.id,form_updated_at:check.form.updated_at,inspector_name:localStorage.getItem('inspection_operator_name'),shift,is_draft:draft,answers:check.answers});check=null;$('#check').remove();await load();toast('saved');}catch(e){toast(['form_not_assigned','form_changed'].includes(e.message)?'formChanged':'error');}}





